{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "서울특별시 동물보호 조례상 확인된 강아지 반환 가능 여부와 보호비 감면 가능 여부",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "보호소에서 확인된 강아지는 돌려받을 수 있습니다. 구청장은 구조한 유기동물의 등록여부를 확인하여 등록된 동물일 경우 해당 동물의 소유자에게 즉시 반환하여야 하며, 보호조치 중인 유기동물에 대하여 소유자가 반환 요구기간 내에 반환을 요구하는 때에는 관련 정보를 확인하고 소유자가 확실한 경우 이를 지체 없이 반환하여야 합니다.",
          "b_ids": "동물보호:제16조제1항, 동물보호:제16조제2항"
        },
        {
          "a_text": "보호비 부담을 줄이거나 감면받을 수 있습니다. 시장 또는 구청장은 보호동물의 입양 활성화를 위하는 경우 또는 소유자등이 경제적 사정상 비용 납부가 어려운 경우에는 보호비용의 전부 또는 일부를 면제할 수 있습니다.",
          "b_ids": "동물보호:제19조제3항"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
